'use strict';
const $=id=>document.getElementById(id),form=$('calculator');
const kr=ore=>new Intl.NumberFormat('da-DK',{style:'currency',currency:'DKK',maximumFractionDigits:0}).format(ore/100);
const exact=ore=>new Intl.NumberFormat('da-DK',{style:'currency',currency:'DKK',minimumFractionDigits:2,maximumFractionDigits:2}).format(ore/100);
const date=v=>v?new Intl.DateTimeFormat('da-DK',{month:'short',year:'numeric'}).format(new Date(Number(v.slice(0,4)),Number(v.slice(5))-1,1)):'Ingen gæld';
let current,guideIndex=0;
function read(){return Object.fromEntries(new FormData(form));}
function explain(){if(!current)return;let r=current;const text=[['Små lån bliver til et samlet beløb.',`Over ${r.study.rows.length} måneder låner du ${kr(r.study.borrowed)}. Med startgæld og ${kr(r.study.interest)} i nye renter bliver gælden ${kr(r.study.debt)} ved studieslut.`],['Pausen er ikke rentefri.',r.payment.start?`Du begynder først at betale i ${date(r.payment.start)}. Imens vokser gælden med ${kr(r.payment.waitInterest)} i vores scenarie. Det er derfor, gælden kan stige, selv om du ikke låner mere.`:'Du har ingen gæld i dette scenarie. Derfor kommer der heller ingen renter eller betalinger efter studiet.'],['Gør plads til betalingen.',r.payment.start?`Den største betaling er ${exact(r.payment.maxPayment)} inklusive gebyr. Sæt ${exact(r.payment.maxPayment/r.interval)} til side hver måned, så beløbet er klar, når regningen kommer.`:'Uden gæld behøver du ikke sætte penge til side til SU-lånet. Prøv et lånebeløb for at se forskellen.']];$('guide-title').textContent=text[guideIndex][0];$('guide-text').textContent=text[guideIndex][1];$('guide-count').textContent=`${guideIndex+1} af 3`;document.querySelectorAll('[data-chapter]').forEach(b=>b.setAttribute('aria-pressed',String(Number(b.dataset.chapter)===guideIndex)));}
function draw(r){const rows=[...r.study.rows,...r.payment.rows];const w=720,h=240,left=62,right=15,top=17,bottom=33;const max=Math.max(10000,...rows.map(x=>x.debt))*1.12;const x=i=>left+i/Math.max(1,rows.length-1)*(w-left-right),y=v=>h-bottom-v/max*(h-top-bottom);let lines='';for(let i=0;i<4;i++){const v=max*i/3;lines+=`<line x1="${left}" y1="${y(v)}" x2="${w-right}" y2="${y(v)}" stroke="#e6eaf1"/><text x="${left-10}" y="${y(v)+4}" text-anchor="end" fill="#68758a" font-size="12">${Math.round(v/100000)}k kr.</text>`;}const points=rows.map((p,i)=>`${x(i).toFixed(2)},${y(p.debt).toFixed(2)}`).join(' ');const endX=x(r.study.rows.length-1);$('chart').innerHTML=`<svg viewBox="0 0 ${w} ${h}" role="img" aria-labelledby="chart-title chart-desc"><title id="chart-title">Gæld fra ${date(r.start)} til ${date(r.payment.end||r.end)}</title><desc id="chart-desc">${kr(r.study.debt)} ved studieslut. ${kr(r.payment.opening)} ved starten af betalingsåret. ${r.payment.end?'Gælden falder til nul i '+date(r.payment.end):'Ingen gæld efter studiet.'}</desc><defs><linearGradient id="shade" x1="0" y1="0" x2="0" y2="1"><stop stop-color="#2745db" stop-opacity=".17"/><stop offset="1" stop-color="#2745db" stop-opacity="0"/></linearGradient></defs>${lines}<polygon points="${left},${h-bottom} ${points} ${x(rows.length-1)},${h-bottom}" fill="url(#shade)"/><line x1="${endX}" x2="${endX}" y1="${top}" y2="${h-bottom}" stroke="#bb8a20" stroke-dasharray="4 4"/><polyline points="${points}" fill="none" stroke="#2745db" stroke-width="3" stroke-linejoin="round"/><circle cx="${endX}" cy="${y(r.study.debt)}" r="5" fill="#f5cf57" stroke="#987211"/><text x="${left}" y="${h-5}" font-size="12" fill="#68758a">${r.start.slice(0,4)}</text><text x="${w-right}" y="${h-5}" text-anchor="end" font-size="12" fill="#68758a">${rows.at(-1).month.slice(0,4)}</text></svg>`;}
function render(r){current=r;$('total').textContent=kr(r.study.debt);$('total-note').textContent=`Heraf ${kr(r.study.interest)} i renter i studieperioden`;$('monthly').textContent=kr(r.payment.maxPayment/r.interval);$('payment-note').textContent=r.payment.start?`${exact(r.payment.maxPayment)} hver ${r.interval===2?'anden':'eneste'} måned inkl. gebyr`:'Ingen lånebetaling';$('free').textContent=date(r.payment.end);$('free-note').textContent=`Med ${String(r.rate).replace('.',',')} % fast scenarierente`;$('date-start').textContent=date(r.start);$('date-end').textContent=date(r.end);$('date-payment').textContent=date(r.payment.start);$('chart-summary').textContent=r.payment.start?`Samlet tilbagebetaling: ${exact(r.payment.total)}, inklusive ${exact(r.payment.fees)} i gebyrer. Før rentefradrag.`:'Du har ingen gæld at betale tilbage.';draw(r);explain();$('budget-result').hidden=!r.budget;if(r.budget){const b=r.budget;$('budget-left').textContent=exact(b.left);$('budget-left').classList.toggle('negative',b.left<0);$('budget-caption').textContent=`${kr(b.net)} indkomst − ${kr(b.expenses)} udgifter − ${exact(b.reserve)} til SU.`;$('cash-note').textContent=`Uden opsparet reserve har du ${exact(b.cash)} tilbage i måneden med den største betaling.`;$('budget-warning').textContent=b.left<0?'Der er underskud med de indtastede tal. Prøv at justere dit scenarie.':'Beløbet skal også dække eventuelle udgifter, du ikke har indtastet.';const max=Math.max(b.net,b.expenses+b.reserve,1);$('budget-bars').innerHTML=[['Udgifter',b.expenses,'expenses'],['SU-reserve',b.reserve,''],['Tilbage',Math.max(0,b.left),'']].map(([label,value,cls])=>`<div class="bar-label"><span>${label}</span><span>${exact(value)}</span></div><div class="bar-track"><div class="bar-fill ${cls}" style="width:${value/max*100}%"></div></div>`).join('');}$('error').textContent='';$('dirty').hidden=true;$('results').removeAttribute('aria-label');document.dispatchEvent(new CustomEvent('su:calculated',{detail:r}));}
form.addEventListener('submit',e=>{e.preventDefault();try{render(SU.calculate(read()));}catch(error){$('error').textContent=error.message;$('results').setAttribute('aria-label','Tidligere beregning. Ret inputfejl for at opdatere.');}});
form.addEventListener('input',()=>{$('dirty').hidden=false;});$('loan-range').addEventListener('input',e=>{$('loan').value=e.target.value;});$('loan').addEventListener('input',e=>{$('loan-range').value=e.target.value;});$('guide-next').addEventListener('click',()=>{guideIndex=(guideIndex+1)%3;explain();});$('guide-prev').addEventListener('click',()=>{guideIndex=(guideIndex+2)%3;explain();});render(SU.calculate(read()));
if(document.modelContext?.registerTool){const life=new AbortController();try{Promise.resolve(document.modelContext.registerTool({name:'calculate_su_scenario',title:'Beregn SU-scenarie',description:'Beregn SU-lån og opdater formular, graf og budget med samme beregning som brugerfladen.',inputSchema:{type:'object',properties:{loan:{type:'number'},debt:{type:'number'},start:{type:'string'},end:{type:'string'},rate:{type:'number'},interval:{type:'integer',enum:[1,2]},net:{type:'number'},expenses:{type:'number'}},required:['loan','debt','start','end','rate','interval'],additionalProperties:false},annotations:{readOnlyHint:false},execute(input){const r=SU.calculate(input);for(const key of ['loan','debt','start','end','rate','interval','net','expenses'])form.elements[key].value=input[key]??'';$('loan-range').value=input.loan;render(r);return {gaeld_ved_studieslut:r.study.debt/100,maanedlig_reserve:r.payment.maxPayment/r.interval/100,gaeldfri:r.payment.end};}},{signal:life.signal})).catch(()=>{});}catch{}window.addEventListener('pagehide',()=>life.abort(),{once:true});}
